#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/.." && pwd)
CONFIG_DIR="$REPO_ROOT/.stellar/mainnet-canary"
cd "$REPO_ROOT"

banner "Stellar 8183 Mainnet canary"

stage "Import the funded Mainnet account"
say "The funded account is funding-only. It transfers at most 58 XLM to fresh canary accounts and is never the contract admin, issuer, client, provider, or evaluator."
say "Enter the key only into the hidden Stellar CLI prompt. Never paste it into chat or .env."
mkdir -p "$CONFIG_DIR"
stellar --config-dir "$CONFIG_DIR" --quiet network add mainnet \
  --rpc-url https://mainnet.sorobanrpc.com/ \
  --network-passphrase 'Public Global Stellar Network ; September 2015'
if stellar --config-dir "$CONFIG_DIR" keys address canary-admin >/dev/null 2>&1; then
  note "canary-admin already exists: $(stellar --config-dir "$CONFIG_DIR" keys address canary-admin)"
elif confirm "Do you have a 12-24 word seed phrase?"; then
  say "Paste all words in one entry. Capitalization, commas, quotes, line breaks, and copied list numbering will be normalized locally."
  printf '  %sPaste the recovery phrase:%s ' "$BOLD" "$RESET"
  read -rs ADMIN_MNEMONIC
  printf '\n'
  printf '%s\n' "$ADMIN_MNEMONIC" | \
    pnpm --filter @trionlabs/8183-console import:mainnet-admin mnemonic
  unset ADMIN_MNEMONIC
elif confirm "Does your key start with S?"; then
  warn "The raw S... key will be stored in the ignored, permission-restricted .stellar directory."
  stellar --config-dir "$CONFIG_DIR" keys add canary-admin --secret-key
else
  say "Hex import accepts exactly 64 hexadecimal characters (32 bytes), optionally prefixed with 0x."
  warn "This must be an Ed25519 seed for the funded Stellar account. An Ethereum/secp256k1 private key does not control the same Stellar address."
  printf '  %sPaste the hexadecimal Ed25519 seed:%s ' "$BOLD" "$RESET"
  read -rs ADMIN_HEX
  printf '\n'
  printf '%s\n' "$ADMIN_HEX" | \
    pnpm --filter @trionlabs/8183-console import:mainnet-admin hex
  unset ADMIN_HEX
fi

stage "Create isolated canary accounts"
say "The deployer, client, provider, and evaluator keys are generated directly in the OS credential store."
for alias in canary-deployer canary-client canary-provider canary-evaluator; do
  if stellar --config-dir "$CONFIG_DIR" keys address "$alias" >/dev/null 2>&1; then
    note "$alias already exists: $(stellar --config-dir "$CONFIG_DIR" keys address "$alias")"
    continue
  fi
  stellar --config-dir "$CONFIG_DIR" keys generate "$alias" --secure-store
done

stage "Fund role accounts"
say "The funding-only account will provision the deployer with 50 XLM, the client with 4 XLM, and the provider and evaluator with 2 XLM each."
for alias in canary-admin canary-deployer canary-client canary-provider canary-evaluator; do
  printf '  %-20s %s\n' "$alias" "$(stellar --config-dir "$CONFIG_DIR" keys address "$alias")"
done
warn "This stage submits Mainnet transactions and spends real XLM."
confirm "Transfer at most 58 XLM into the four isolated canary accounts now?" || exit 1
pnpm --filter @trionlabs/8183-console setup:mainnet --fund-mainnet-roles

stage "Validate the pinned canary build"
say "This checks a clean source commit, rebuilds both Wasm files, checks hashes, verifies Mainnet health, and confirms all four accounts."
pnpm --filter @trionlabs/8183-console preflight:mainnet check

stage "Prepare deterministic deployment plan"
pnpm --filter @trionlabs/8183-console deploy:mainnet --prepare-plan
step "Review artifacts/mainnet-canary/deployment-plan.json."
if command -v jq >/dev/null 2>&1; then
  jq . artifacts/mainnet-canary/deployment-plan.json
else
  sed -n '1,240p' artifacts/mainnet-canary/deployment-plan.json
fi
pause "Press Enter after checking every account, contract ID, hash, and valueless-asset warning."

stage "Deploy the Mainnet canary"
warn "This submits Mainnet transactions and spends real XLM. DEMO8183 has no value and must remain inside the canary accounts."
confirm "Deploy exactly this reviewed plan?" || exit 1
pnpm --filter @trionlabs/8183-console deploy:mainnet --execute-valueless-mainnet-canary

stage "Execute three terminal paths"
warn "This submits more Mainnet transactions and waits about two minutes for the expiry path."
confirm "Run completion, funded rejection, and expired refund now?" || exit 1
pnpm --filter @trionlabs/8183-console canary:mainnet --execute-valueless-mainnet-canary

stage "Assemble public evidence"
pnpm --filter @trionlabs/8183-console assemble:canary artifacts/mainnet-canary
CLIENT_ADDRESS=$(stellar --config-dir "$CONFIG_DIR" keys address canary-client)
pnpm --filter @trionlabs/8183-console verify:canary \
  artifacts/mainnet-canary/canary-evidence.json "$CLIENT_ADDRESS"

stage "Review final artifacts"
say "The deployment, receipts, transaction archive, hashes, and verified evidence are in artifacts/mainnet-canary/."
step "Publish only reviewed public evidence. Never publish .stellar/ or deployments/private/."
note "The author-run canary proves Mainnet compatibility. It does not count as Yaman's independent customer pilot."

finish
